Method.Implementation:
  set tSC = $$$OK


  set timeOut = ..TimeInSecs

  #dim statement As %SQL.Statement = ##class(%SQL.Statement).%New()

  For ind=1:1:$L(..Source, ",")
  {
  	set srcComp = $P(..Source,",", ind)

  	if (srcComp '= "")
  	{
			set tSC = statement.%PrepareClassQuery("Ens.Queue","EnumerateItem")
			#dim rset As %SQL.StatementResult = statement.%Execute(srcComp, "") 

			while rset.%Next() 
			{

				set id = rset.%Get("Index")
				set msgId = rset.%Get("MessageId")

				&SQL(SELECT
					DATEDIFF('ss',TimeCreated, GETUTCDATE(CURRENT_TIMESTAMP) ) into tmdiff
					FROM Ens.MessageHeader
					WHERE ID = :msgId)

					$$$TRACE( srcComp _", ID: " _  msgId _ " is " _ tmdiff _" secs old")

				if ( tmdiff > timeOut)
				  {
					set pPriority = $$$eMessagePrioritySync 
					Set tSC = ##class(Ens.Queue).AbortItem(srcComp,pPriority,id)
					If $$$ISOK(tSC) {
					   $$$TRACE( "Abort: " _ id)
					} Else {
					   $$$TRACE( "Abort failed for message with index "_id_": "_$$$StatusDisplayString(tSC))
					}
				  }

			}
  	}
  }


  $$$TRACE( "-- Done -- ")
  return tSC
